a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; }
input { font-family: inherit; }

/* ── HEADER ── */
.header {
  position: absolute;
  top: 0; left: 0; right: 0;
  z-index: 100;
  padding: 20px 4%;
  display: flex;
  align-items: center;
  justify-content: space-between;
