  align-items: center;
  gap: 16px;
}

.lang-select {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--text-muted);
  padding: 4px 12px;
  border-radius: 4px;
  font-size: 0.85rem;
  cursor: pointer;
}
.lang-select option { background: var(--bg-primary); }

.btn-signin {
  background: var(--accent);
  color: white;
  padding: 6px 18px;
  border-radius: 4px;
  font-size: 0.9rem;
  font-weight: 600;
  transition: background 0.2s;
