.btn-signin:hover { background: var(--accent-hover); }

/* ── HERO ── */
.hero {
  position: relative;
  min-height: 700px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 140px 4% 80px;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.hero-bg::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    linear-gradient(to top, var(--bg-primary) 0%, transparent 40%),
    linear-gradient(to bottom, rgba(0,0,0,0.6) 0%, transparent 40%);
  z-index: 1;
}

.poster-grid {
  position: absolute;
  inset: -60px;
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  grid-template-rows: repeat(4, 1fr);
  gap: 8px;
  transform: rotate(-12deg) scale(1.3);
  opacity: 0.18;
}

.poster-cell {
  border-radius: 6px;
  background: linear-gradient(135deg, #1a1a2e, #16213e);
  min-height: 120px;
}
.poster-cell:nth-child(odd) { background: linear-gradient(135deg, #0f3460, #1a1a2e); }
.poster-cell:nth-child(3n) { background: linear-gradient(135deg, #533483, #1a1a2e); }
.poster-cell:nth-child(5n) { background: linear-gradient(135deg, #e94560, #1a1a2e); }
.poster-cell:nth-child(7n) { background: linear-gradient(135deg, #0a3d62, #1a1a2e); }

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 740px;
}

.hero h1 {
  font-size: clamp(2rem, 5vw, 3.2rem);
  font-weight: 900;
  line-height: 1.1;
  margin-bottom: 16px;
  letter-spacing: -0.5px;
}

.hero .subtitle {
  font-size: clamp(1.1rem, 2.5vw, 1.5rem);
  font-weight: 400;
  margin-bottom: 28px;
  color: var(--text-primary);
}

.hero .prompt-text {
  font-size: 1.1rem;
  margin-bottom: 16px;
  color: var(--text-primary);
}

.email-form {
