  border-right: none;
  border-radius: 4px 0 0 4px;
  color: white;
  outline: none;
  transition: border-color 0.2s;
}
.email-form input[type="email"]::placeholder { color: var(--text-muted); }
.email-form input[type="email"]:focus { border-color: var(--text-primary); }

.btn-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--accent);
  color: white;
  padding: 16px 28px;
  font-size: 1.1rem;
  font-weight: 700;
  border-radius: 0 4px 4px 0;
  white-space: nowrap;
  transition: background 0.2s;
}
.btn-cta:hover { background: var(--accent-hover); }

.btn-cta svg {
  width: 20px;
  height: 20px;
  fill: currentColor;
}

/* ── SECTION DIVIDERS ── */
.section-divider {
  height: var(--section-gap);
  background: #232323;
}

/* ── TRENDING ── */
.trending {
  padding: 60px 4% 60px;
  background: var(--bg-primary);
}

.section-title {
  font-size: clamp(1.3rem, 3vw, 1.7rem);
  font-weight: 800;
  margin-bottom: 28px;
}

.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: 10px;
  -webkit-overflow-scrolling: touch;
}
.carousel-track::-webkit-scrollbar { display: none; }

.carousel-card {
  flex: 0 0 200px;
  position: relative;
  border-radius: 6px;
  overflow: hidden;
  cursor: pointer;
  transition: transform 0.3s;
}
.carousel-card:hover { transform: scale(1.05); }

.card-poster {
