.poster-1 .card-poster-bg { background: linear-gradient(160deg, #8B0000, #2d0000); }
.poster-2 .card-poster-bg { background: linear-gradient(160deg, #b8860b, #3d2e00); }
.poster-3 .card-poster-bg { background: linear-gradient(160deg, #ff69b4, #4a0028); }
.poster-4 .card-poster-bg { background: linear-gradient(160deg, #2e8b57, #0d2818); }
.poster-5 .card-poster-bg { background: linear-gradient(160deg, #9370db, #2d1b4e); }
.poster-6 .card-poster-bg { background: linear-gradient(160deg, #b22222, #3d0c0c); }
.poster-7 .card-poster-bg { background: linear-gradient(160deg, #4682b4, #1a3a52); }
.poster-8 .card-poster-bg { background: linear-gradient(160deg, #ff6347, #4d1f17); }
.poster-9 .card-poster-bg { background: linear-gradient(160deg, #ffd700, #4d4000); }
.poster-10 .card-poster-bg { background: linear-gradient(160deg, #da70d6, #3d1f3a); }

.card-poster .poster-title {
