}

.faq-list {
  max-width: 820px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.faq-item {
  background: var(--bg-elevated);
  border-radius: 4px;
  overflow: hidden;
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  font-size: 1.1rem;
  font-weight: 500;
  color: var(--text-primary);
  background: var(--bg-elevated);
  border: none;
  text-align: left;
  cursor: pointer;
  transition: background 0.2s;
}
.faq-question:hover { background: var(--divider); }

.faq-icon {
  font-size: 1.6rem;
  font-weight: 300;
  transition: transform 0.3s;
  flex-shrink: 0;
  margin-left: 16px;
}

.faq-item.active .faq-icon { transform: rotate(45deg); }

.faq-answer {
  max-height: 0;
