}

.faq-item.active .faq-answer {
  max-height: 400px;
}

.faq-answer-inner {
  padding: 0 24px 24px;
  font-size: 1rem;
  color: var(--text-secondary);
  line-height: 1.7;
  border-top: 1px solid var(--bg-primary);
  padding-top: 20px;
}

.faq-cta {
  text-align: center;
  margin-top: 40px;
  max-width: 820px;
  margin-left: auto;
  margin-right: auto;
}

.faq-cta .prompt-text {
  font-size: 1.1rem;
  margin-bottom: 16px;
}

/* ── BOTTOM CTA ── */
.bottom-cta {
  padding: 60px 4%;
  text-align: center;
  background: var(--bg-primary);
}

.bottom-cta .prompt-text {
  font-size: 1.1rem;
  margin-bottom: 16px;
}

.bottom-cta .email-form {
  max-width: 600px;
  margin: 0 auto;
}

/* ── FOOTER ── */
.footer {
  padding: 50px 4% 30px;
  background: var(--bg-primary);
  border-top: 1px solid #232323;
  color: var(--text-muted);
}

.footer-contact {
  font-size: 0.95rem;
  margin-bottom: 28px;
  color: var(--text-secondary);
}
.footer-contact a { text-decoration: underline; }

.footer-links {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px 24px;
  margin-bottom: 28px;
}

.footer-links a {
  font-size: 0.85rem;
  color: var(--text-muted);
  text-decoration: underline;
  transition: color 0.2s;
}
.footer-links a:hover { color: var(--text-secondary); }

.footer-bottom {
  display: flex;
  align-items: center;
  gap: 16px;
