/* ── RESPONSIVE ── */
@media (max-width: 1024px) {
  .features-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .header { padding: 16px 4%; }
  .logo { font-size: 1.4rem; }

  .hero { min-height: 580px; padding: 120px 4% 60px; }

  .email-form {
    flex-direction: column;
    gap: 12px;
  }
  .email-form input[type="email"] {
    border-right: 1px solid var(--text-muted);
    border-radius: 4px;
  }
  .btn-cta {
    border-radius: 4px;
    justify-content: center;
  }

  .carousel-card { flex: 0 0 160px; }
  .rank-number { font-size: 5rem; }

  .features-grid { grid-template-columns: 1fr; }

  .footer-links { grid-template-columns: repeat(2, 1fr); }

  .carousel-arrow { width: 40px; height: 40px; font-size: 1.1rem; }
}

@media (max-width: 480px) {
  .hero h1 { font-size: 1.8rem; }
  .hero .subtitle { font-size: 1.1rem; }
  .carousel-card { flex: 0 0 140px; }
  .rank-number { font-size: 4rem; }
  .faq-question { font-size: 0.95rem; padding: 16px 18px; }
}
</style>
